INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65275775', 65275775, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'UNIT PENYELENGGARA BANDAR UDARA RAHADI OESMAN DI KETAPANG', 'Belanja Pemeliharaan Jalan dan Jembatan (Jalan Masuk Bandara) 6384 M2', 'Pekerjaan Konstruksi', 'Penunjukan Langsung', 'Kalimantan Barat, Ketapang (Kab.)', 159600000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '6384 M2', 'Belanja pemeliharaan jalan masuk bandara seluas ±6.384 m² berupa pemeliharaan rutin dan berkala untuk menjaga kelancaran akses kendaraan, keselamatan pengguna, dan kelaikan fungsi jalan, meliputi pembersihan permukaan, perawatan bahu dan drainase, penambalan lubang, perbaikan retak dan deformasi perkerasan, perataan dan pemadatan ulang, pelapisan/overlay tipis bila diperlukan, serta perapian marka dan fasilitas pendukung agar jalan tetap rata, kuat, dan aman digunakan.', 'Pekerjaan mencakup pembersihan permukaan jalan dari kotoran, pasir, dan genangan air, perawatan bahu jalan dan saluran drainase, penambalan lubang (patching) dengan campuran aspal/beton sesuai jenis perkerasan, perbaikan retak (crack sealing), perbaikan deformasi/gelombang, perataan dan pemadatan kembali, serta pelapisan ulang tipis (overlay) bila kondisi perkerasan memerlukan. Termasuk pengecatan atau perapian marka jalan, perbaikan tepi jalan/kerb, pembongkaran bagian rusak, pengangkutan material sisa, mobilisasi–demobilisasi peralatan, dan pekerjaan pendukung lainnya. Material yang digunakan harus baru dan memenuhi spesifikasi teknis perkerasan jalan yang berlaku. Pelaksanaan wajib menerapkan K3, pengaturan lalu lintas selama pekerjaan, serta pengendalian mutu, sehingga hasil akhir jalan bersih, rata, kuat, dan laik fungsi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2020499);
