INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65275466', 65275466, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'UNIT PENYELENGGARA BANDAR UDARA RAHADI OESMAN DI KETAPANG', 'Belanja Pemeliharaan Gedung dan Bangunan (Bangunan Operasional) 1472 M2', 'Pekerjaan Konstruksi', 'Penunjukan Langsung', 'Kalimantan Barat, Ketapang (Kab.)', 147200000, 'April 2026', 'APBN - PNBP (D)', 1, 1, '1472 M2', 'Belanja pemeliharaan Gedung dan Bangunan berupa pemeliharaan Bangunan Operasional seluas ±1.472 m² yang mencakup kegiatan perawatan rutin dan perbaikan berkala guna menjaga fungsi, keamanan, dan kenyamanan bangunan, meliputi pembersihan area, perbaikan atap dan plafon, dinding serta pengecatan ulang, perbaikan lantai, pintu dan jendela, perawatan instalasi listrik dan penerangan, instalasi air bersih dan sanitasi, perbaikan drainase, serta perbaikan fasilitas pendukung lainnya sehingga bangunan tetap laik fungsi, aman, dan mendukung kelancaran kegiatan operasional.', 'Pekerjaan meliputi pemeliharaan rutin dan perbaikan berkala bangunan operasional guna menjaga kelayakan fungsi, keamanan, dan kenyamanan pengguna. Kegiatan mencakup pembersihan dan penataan area, perbaikan atap (penutup atap, rangka, talang), perbaikan plafon, perbaikan dinding (retak/plester/aci), serta pengecatan ulang interior dan eksterior. Termasuk perbaikan atau penggantian lantai/keramik/beton rusak, perawatan pintu, jendela, kusen, engsel, dan kunci, pemeliharaan instalasi listrik dan penerangan (lampu, saklar, stop kontak, panel ringan), perawatan instalasi air bersih, sanitasi, dan pembuangan, perbaikan drainase sekitar bangunan, serta penggantian komponen bangunan yang rusak ringan. Material yang digunakan harus baru, berkualitas baik, dan memenuhi standar teknis bangunan gedung. Pelaksanaan pekerjaan wajib menerapkan K3, menjaga kebersihan dan keamanan lingkungan kerja, serta dilakukan bertahap agar tidak mengganggu kegiatan operasional, dengan hasil akhir bangunan bersih, rapi, aman, dan laik fungsi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2020742);
