INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65242310', 65242310, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Junior Analisis Country Partnership Strategy (CPS) Mitra Pembangunan Luar Negeri', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 99600000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'a. Melakukan analisis teknis terkait penyelarasan dokumen CPS dan kerja sama pembangunan luar negeri lainnya dengan berbagai mitra pembangunan bilateral maupun multilateral sesuai prioritas nasional; didahului dengan identifikasi prioritas pembangunan pemerintah dan tiap mitra pembangunan luar negeri. b. Melakukan analisis portofolio pembiayaan dan hibah luar negeri melalui pengumpulan, verifikasi, dan analisis dasar atas informasi kinerja proyek, untuk mendukung penyusunan laporan portofolio serta identifikasi isu. c. Menyusun rekomendasi atas implementasi yang memerlukan tindak lanjut bersama Kementerian/Lembaga pelaksana dan mitra pembangunan. d. Mendukung penyelenggaraan rapat koordinasi bilateral/multilateral, courtesy call, high-level meetings, serta forum kebijakan lainnya dengan menyiapkan konsep bahan rapat, talking points, notula, laporan tindak lanjut; termasuk melakukan komunikasi kerja terkait dengan mitra pembangunan, K/L pelaksana, dan unit teknis di Kementerian PPN/Bappenas. e. Melakukan analisis perkembangan, peluang, serta kebutuhan penyesuaian kerja sama pembiayaan pembangunan lainnya, termasuk pemutakhiran informasi yang relevan untuk mendukung penyusunan CPS dan dokumen kerja sama strategis.', 'a. Melakukan analisis teknis terkait penyelarasan dokumen CPS dan kerja sama pembangunan luar negeri lainnya dengan berbagai mitra pembangunan bilateral maupun multilateral sesuai prioritas nasional; didahului dengan identifikasi prioritas pembangunan pemerintah dan tiap mitra pembangunan luar negeri. b. Melakukan analisis portofolio pembiayaan dan hibah luar negeri melalui pengumpulan, verifikasi, dan analisis dasar atas informasi kinerja proyek, untuk mendukung penyusunan laporan portofolio serta identifikasi isu. c. Menyusun rekomendasi atas implementasi yang memerlukan tindak lanjut bersama Kementerian/Lembaga pelaksana dan mitra pembangunan. d. Mendukung penyelenggaraan rapat koordinasi bilateral/multilateral, courtesy call, high-level meetings, serta forum kebijakan lainnya dengan menyiapkan konsep bahan rapat, talking points, notula, laporan tindak lanjut; termasuk melakukan komunikasi kerja terkait dengan mitra pembangunan, K/L pelaksana, dan unit teknis di Kementerian PPN/Bappenas. e. Melakukan analisis perkembangan, peluang, serta kebutuhan penyesuaian kerja sama pembiayaan pembangunan lainnya, termasuk pemutakhiran informasi yang relevan untuk mendukung penyusunan CPS dan dokumen kerja sama strategis.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2027096);
